import{_ as i,o as n,c as a,a2 as t}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Tinkering","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/tinkering.md","filePath":"guide/professions/tinkering.md"}'),s={name:"guide/professions/tinkering.md"};function r(o,e,d,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="tinkering" tabindex="-1">Tinkering <a class="header-anchor" href="#tinkering" aria-label="Permalink to &quot;Tinkering&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/tinkering.html">full design specification</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Tinkering explores precision mechanisms through inspection, design, assembly, calibration, testing and maintenance. Power, motion, triggers, control and output form a bounded language for devices rather than unlimited automation.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>A tinkerer could diagnose traps, repair machinery, restore lifts or bridges and operate dungeon devices. Locks and security are another direction: Tinkering understands and builds them, while Lockpicking defeats them. Traps can combine mechanisms with <a href="/Syrolands-Public/guide/professions/alchemy.html">Alchemy</a> payloads.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>The Mechanist’s Journal grows through observation and reverse engineering. Disassembling an unfamiliar device might reveal clues or techniques while risking damage. Precision devices, reliable locks and mechanism expertise offer different identities, supported by <a href="/Syrolands-Public/guide/professions/overview.html">shared learning and production</a>.</p><h2 id="future-directions-and-limits" tabindex="-1">Future directions and limits <a class="header-anchor" href="#future-directions-and-limits" aria-label="Permalink to &quot;Future directions and limits&quot;">​</a></h2><p>Bounded housing mechanisms could run gates, alarms or feeders. Burglary would need detection, countermeasures and escalating risk; trivial unattended lockpicking or total house loss must be prevented. Automatons and mechanical golems are future high-end specializations, potentially involving <a href="/Syrolands-Public/guide/professions/blacksmithing.html">Blacksmithing</a>, Alchemy and perhaps magic. Security rules, automation limits and construct systems are not finalized.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/game-design/professions/tinkering.html">Full design specification</a></p>',11)])])}const m=i(s,[["render",r]]);export{g as __pageData,m as default};
